    await setDoc(pref,{...put,by:auth.currentUser.uid,at:Date.now()},{merge:true});
    const chk=await getDocFromServer(pref);if(!chk.exists()||PHK.some(k=>put[k]&&(chk.data()[k]||[]).length!==put[k].length))throw Error('tasveer pakki nahi hui');   // pehle pakki, phir hi purani jagah se hatao
    const cur=await getDocFromServer(ref(r.id));if(!cur.exists())continue;
    await updateDoc(ref(r.id),{photos:deleteField(),billPhotos:deleteField(),goodsPhotos:deleteField(),pn,rev:(cur.data().rev||0)+1,updatedAt:Date.now(),updatedBy:auth.currentUser.uid});
